var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDistributedMemoryCache();          // or AddStackExchangeRedisCache
builder.Services.AddSession(o => { o.IdleTimeout = TimeSpan.FromMinutes(20);
                                   o.Cookie.HttpOnly = true; });
var app = builder.Build();
app.UseRouting();
app.UseSession();                                        // after routing, before endpoints
app.MapGet("/cart", (HttpContext ctx) => {
    ctx.Session.SetString("step", "payment");
    return ctx.Session.GetString("step");
});
